sys_ui_action.client_script_v2:
var rejecttaskflag = '';
var taskCountMessage = '';
var updatedTaskCount = 0;

function onClick(g_form) {

    var missingFields = getMissingFields();
    if (missingFields.length > 0) {
        g_form.addErrorMessage('The following mandatory fields are not filled in: ' + missingFields);
        return false;
    }
    /*
  // MSSCUSTODY-4328
    var mandatoryfields = g_form.getMissingFields();
    if (mandatoryfields.length > 0) {
        g_form.addErrorMessage('The following mandatory fields are not filled in: ' + mandatoryfields.toString());
        return false;
    }*/



    // MSSCUSTODY-3978
    var currentUserId = g_scratchpad.loggeduserID;
    if (currentUserId == g_form.getValue('current_maker_assignee')) {
        alert('Checker cannot be the same user who actioned the maker task');
        return false;
    }
    // MSSCUSTODY - 3658
    if (g_scratchpad.approvalAccessChecker == 'false') {
        g_form.addErrorMessage(g_scratchpad.usrChekcerBulkMessage);
        return false;
    }
    var checkerCount = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils");
    checkerCount.addParam("sysparm_name", "getCheckerTaskCount");
    checkerCount.addParam("sysparm_bulkid", g_form.getUniqueValue());
    checkerCount.getXMLAnswer(countresponse);

    var gajax = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils"); // getting count of checker and checker to be rejected tasks
    gajax.addParam("sysparm_name", "getCheckerTaskCount");
    gajax.addParam("sysparm_bulkid", g_form.getUniqueValue());
    gajax.getXMLAnswer(response);
}

function countresponse(answer) {
    // MSSCUSTODY-3282 - Verify Task Count before submitting the bulk
    // MSSCUSTODY-4282   
    var initialTasksCount = g_form.getValue('active_trade_count'); // g_scratchpad.checkTaskCount; // Fetch scratchpad data
    updatedTaskCount = 0;
    var taskCount = JSON.parse(answer);
    // MSSCUSTODY-4282 - Total Linked is sum of Checker to be rejected and Checker Approved.
    // var totalLinkedTaskCount = taskCount.chkCount + taskCount.chkRejCount;
    // MSSCUSTODY-5475 - defect fix
    var rejcount = taskCount.chkRejCount;
    if (rejcount == undefined || rejcount.toString() == "undefined") {
        taskCount.chkRejCount = 0;
    }
    var totalLinkedTaskCount = parseInt(taskCount.chkCount) + parseInt(taskCount.chkRejCount);
    // var onSubmitCount = taskCount.chkCount;
    // Compare taskCount and display message based on task Count
    if (initialTasksCount != totalLinkedTaskCount) {
        // if (initialTasksCount == 0 || initialTasksCount < onSubmitCount) {
        //     taskCountMessage = '';
        // } else {
        updatedTaskCount = initialTasksCount - totalLinkedTaskCount;
        taskCountMessage = ('Tasks not Submitted due to GHSS update : ' + updatedTaskCount + '\n');
        // }
    }
}

function response(answer) {
    var count = JSON.parse(answer);
    // get count of checker tasks
    if (count.chkCount) { // if checker tasks present
        var approvetaskCount = parseInt(count.chkCount);
        var approvetaskflag = 'true';
    } else { // if no checker tasks set flag as false and count as zero
        approvetaskCount = '0';
        approvetaskflag = 'false';
    }

    // get count of checker to be rejected tasks
    if (count.chkRejCount) { // if checker to be rejected tasks are present set flag as true.
        var rejecttaskCount = parseInt(count.chkRejCount);
        rejecttaskflag = 'true';
        if (updatedTaskCount != 0 || updatedTaskCount > rejecttaskCount) {
            updatedTaskCount = updatedTaskCount - rejecttaskCount;
            if (updatedTaskCount == 0) {
                taskCountMessage = '';
            } else {
                taskCountMessage = ('Task not Submitted due to GHSS update : ' + updatedTaskCount + '\n');
            }
        }
    } else { // if no checker to be rejected tasks set flag as false and count as zero
        rejecttaskCount = '0';
        rejecttaskflag = 'false';
    }


    if (approvetaskflag == 'true' && rejecttaskflag == 'true') {
        var conf = confirm(taskCountMessage + 'Number of checker task to approve : ' + approvetaskCount + ' \nNumber of task to reject : ' + rejecttaskCount + ' \nDo you want to proceed?');
    } else if (approvetaskflag == 'true' && rejecttaskflag == 'false') {
        conf = confirm(taskCountMessage + 'Number of checker task to approve : ' + approvetaskCount + ' \nDo you want to proceed?');
    } else if (approvetaskflag == 'false' && rejecttaskflag == 'true') {
        conf = confirm('You are going to Reject ' + rejecttaskCount + ' Checker Tasks in this bulk. Do you want to proceed?');
    }


    if (conf) {
        //gsftSubmit(null, g_form.getFormElement(), 'submit_checker');
        g_form.save();

        /*
        g_navigation.open('/x_hsb11_mss_c_proc_mss_custody_task_list.do?sysparm_view=bulk_tasks&sysparm_userpref_module=b758b7cb1b6e4ed46ed00e1ad34bcbb3&sysparm_query=active=true^bulk_id.numberISNOTEMPTY^GROUPBYbulk_id&sysparm_filter_only=true');
		*/
        g_aw.closeRecord();

        var gajax = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils");
        gajax.addParam("sysparm_name", "updateCheckerTask");
        gajax.addParam("sysparm_bulkid", g_form.getUniqueValue());
        gajax.addParam("sysparm_assignmentgroup", g_form.getValue('assignment_group'));
        gajax.addParam("sysparm_assignedto", g_form.getValue('assigned_to'));
        gajax.addParam("sysparm_decision_reason", g_form.getValue('decision_reason'));
        gajax.addParam("sysparm_makerAssignmentgroup", g_form.getValue('maker_assignment_group'));
        gajax.addParam("sysparm_reasondescription", g_form.getValue('reason_description'));
        gajax.addParam("sysparm_newMakerasignee", g_form.getValue('new_maker_task_assignee'));
        gajax.addParam("sysparm_comments", g_form.getValue('comments'));
        gajax.addParam("sysparm_rejecttaskflag", rejecttaskflag);
        gajax.getXMLAnswer(response);

        function response(answer) {}
    } else {
        location.reload();
    }

}

function filterForMissingMandatoryFields(field) {
    // Check if the field is mandatory
    if (g_form.isMandatory(field)) {
        // Return true if there is no value
        return !g_form.getValue(field);
    }
}

function getMissingFields() {
    // Get all fields
    var fieldList = g_form.getFieldNames();

    // Return only mandatory fields that have no value
    return fieldList.filter(filterForMissingMandatoryFields);
}
